CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', whatsapp text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=(SELECT auth.uid()) OR (SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=(SELECT auth.uid())) WITH CHECK(id=(SELECT auth.uid()));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE TABLE public.saas_accounts (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, plan text NOT NULL DEFAULT 'none' CHECK(plan IN ('none','starter','creator','pro','agency')), credits integer NOT NULL DEFAULT 0 CHECK(credits>=0), trial_seconds integer NOT NULL DEFAULT 0 CHECK(trial_seconds BETWEEN 0 AND 90));
GRANT SELECT ON public.saas_accounts TO authenticated; GRANT ALL ON public.saas_accounts TO service_role;
ALTER TABLE public.saas_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY accounts_read ON public.saas_accounts FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) OR (SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,email,whatsapp) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'name',''),150),coalesce(NEW.email,''),left(coalesce(NEW.raw_user_meta_data->>'whatsapp',''),30)); INSERT INTO public.saas_accounts(user_id) VALUES(NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_customer_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER motionmro_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.app_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), sales_enabled boolean NOT NULL DEFAULT false, infinite_handle text NOT NULL DEFAULT 'paguemro', render_url text NOT NULL DEFAULT '', model text NOT NULL DEFAULT 'gpt-6.1-terra', prices jsonb NOT NULL DEFAULT '{"modelos":{"gpt-6.1-terra":{"entrada":5,"saida":20}},"transcricaoMin":0.006,"vozMilChars":0.3,"dolar":5.5}'::jsonb);
GRANT SELECT ON public.app_settings TO anon,authenticated; GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.app_settings FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.private_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), openai_encrypted text NOT NULL DEFAULT '');
GRANT ALL ON public.private_settings TO service_role;
ALTER TABLE public.private_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.customer_projects (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('motion','overlay','editor','job')), name text NOT NULL DEFAULT '', data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.customer_projects TO authenticated; GRANT ALL ON public.customer_projects TO service_role;
ALTER TABLE public.customer_projects ENABLE ROW LEVEL SECURITY;
CREATE INDEX projects_owner_date ON public.customer_projects(user_id,updated_at DESC);
CREATE POLICY projects_read ON public.customer_projects FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) OR (SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE POLICY projects_insert ON public.customer_projects FOR INSERT TO authenticated WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY projects_update ON public.customer_projects FOR UPDATE TO authenticated USING(user_id=(SELECT auth.uid())) WITH CHECK(user_id=(SELECT auth.uid()));
CREATE POLICY projects_delete ON public.customer_projects FOR DELETE TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE TABLE public.trial_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trial_codes TO authenticated; GRANT ALL ON public.trial_codes TO service_role;
ALTER TABLE public.trial_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY trial_codes_admin ON public.trial_codes FOR SELECT TO authenticated USING((SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE TABLE public.trial_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, code_id uuid NOT NULL REFERENCES public.trial_codes(id), ip_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trial_claims TO authenticated; GRANT ALL ON public.trial_claims TO service_role;
ALTER TABLE public.trial_claims ENABLE ROW LEVEL SECURITY;
CREATE INDEX trial_claim_code ON public.trial_claims(code_id);
CREATE POLICY claims_admin ON public.trial_claims FOR SELECT TO authenticated USING((SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE FUNCTION public.claim_trial(p_user uuid,p_code text,p_ip text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN SELECT id INTO c FROM public.trial_codes WHERE code=upper(trim(p_code)) AND enabled FOR UPDATE; IF c IS NULL THEN RAISE EXCEPTION 'Código inválido ou desativado'; END IF; INSERT INTO public.trial_claims(user_id,code_id,ip_hash) VALUES(p_user,c,p_ip); UPDATE public.saas_accounts SET trial_seconds=90 WHERE user_id=p_user; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Este IP ou cadastro já utilizou um teste'; END $$;
REVOKE ALL ON FUNCTION public.claim_trial(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_trial(uuid,text,text) TO service_role;
CREATE TABLE public.generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, project_id uuid NOT NULL, seconds integer NOT NULL CHECK(seconds BETWEEN 1 AND 600), credits integer NOT NULL DEFAULT 0, trial boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','complete','failed')), calls integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.generations TO authenticated; GRANT ALL ON public.generations TO service_role;
ALTER TABLE public.generations ENABLE ROW LEVEL SECURITY;
CREATE INDEX generations_owner ON public.generations(user_id,created_at DESC); CREATE INDEX generations_project ON public.generations(project_id);
CREATE UNIQUE INDEX generation_one_active ON public.generations(user_id,project_id) WHERE status='active';
CREATE POLICY generations_read ON public.generations FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) OR (SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE FUNCTION public.reserve_generation(p_user uuid,p_project uuid,p_seconds integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.saas_accounts; g uuid; cost integer; sales boolean; is_trial boolean:=false; max_duration integer; BEGIN IF p_seconds<1 OR p_seconds>600 THEN RAISE EXCEPTION 'Duração inválida'; END IF; SELECT * INTO a FROM public.saas_accounts WHERE user_id=p_user FOR UPDATE; SELECT id INTO g FROM public.generations WHERE user_id=p_user AND project_id=p_project AND status='active'; IF g IS NOT NULL THEN RETURN g; END IF; SELECT coalesce(sales_enabled,false) INTO sales FROM public.app_settings WHERE id=true; IF public.has_role(p_user,'admin') THEN cost:=0; ELSIF a.trial_seconds>=p_seconds THEN is_trial:=true; cost:=0; UPDATE public.saas_accounts SET trial_seconds=trial_seconds-p_seconds WHERE user_id=p_user; ELSE IF NOT coalesce(sales,false) THEN RAISE EXCEPTION 'Vendas desativadas: use um código de teste válido'; END IF; max_duration:=CASE a.plan WHEN 'starter' THEN 90 WHEN 'none' THEN 0 ELSE 600 END; IF p_seconds>max_duration THEN RAISE EXCEPTION 'A duração ultrapassa o seu plano'; END IF; cost:=CASE WHEN p_seconds<=30 THEN 10 WHEN p_seconds<=60 THEN 15 WHEN p_seconds<=90 THEN 20 WHEN p_seconds<=180 THEN 30 WHEN p_seconds<=300 THEN 50 ELSE 100 END; IF a.credits<cost THEN RAISE EXCEPTION 'Saldo insuficiente ou limite de teste atingido'; END IF; UPDATE public.saas_accounts SET credits=credits-cost WHERE user_id=p_user; END IF; INSERT INTO public.generations(user_id,project_id,seconds,credits,trial) VALUES(p_user,p_project,p_seconds,cost,is_trial) RETURNING id INTO g; RETURN g; END $$;
REVOKE ALL ON FUNCTION public.reserve_generation(uuid,uuid,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_generation(uuid,uuid,integer) TO service_role;
CREATE FUNCTION public.generation_call(p_user uuid,p_project uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.generations; BEGIN SELECT * INTO g FROM public.generations WHERE user_id=p_user AND project_id=p_project AND status='active' FOR UPDATE; IF g.id IS NULL OR g.calls>=ceil(g.seconds/3.0)*3+8 THEN RAISE EXCEPTION 'Produção não autorizada ou limite de chamadas atingido'; END IF; UPDATE public.generations SET calls=calls+1 WHERE id=g.id; RETURN g.id; END $$;
REVOKE ALL ON FUNCTION public.generation_call(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.generation_call(uuid,uuid) TO service_role;
CREATE FUNCTION public.finish_generation(p_user uuid,p_project uuid,p_failed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.generations; BEGIN SELECT * INTO g FROM public.generations WHERE user_id=p_user AND project_id=p_project AND status='active' FOR UPDATE; IF g.id IS NULL THEN RETURN; END IF; UPDATE public.generations SET status=CASE WHEN p_failed THEN 'failed' ELSE 'complete' END WHERE id=g.id; IF p_failed THEN UPDATE public.saas_accounts SET credits=credits+g.credits,trial_seconds=least(90,trial_seconds+CASE WHEN g.trial THEN g.seconds ELSE 0 END) WHERE user_id=p_user; END IF; END $$;
REVOKE ALL ON FUNCTION public.finish_generation(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_generation(uuid,uuid,boolean) TO service_role;
CREATE TABLE public.usage_costs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, project_id uuid NOT NULL, generation_id uuid REFERENCES public.generations(id), kind text NOT NULL, stage text NOT NULL, model text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, units numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.usage_costs TO authenticated; GRANT ALL ON public.usage_costs TO service_role;
ALTER TABLE public.usage_costs ENABLE ROW LEVEL SECURITY;
CREATE INDEX costs_owner ON public.usage_costs(user_id,created_at DESC); CREATE INDEX costs_generation ON public.usage_costs(generation_id); CREATE INDEX costs_project ON public.usage_costs(project_id);
CREATE POLICY costs_admin ON public.usage_costs FOR SELECT TO authenticated USING((SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE TABLE public.payment_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, plan text NOT NULL CHECK(plan IN ('starter','creator','pro','agency')), amount integer NOT NULL, credits integer NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','expired')), checkout_url text, slug text, transaction_nsu text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), check_until timestamptz NOT NULL DEFAULT now()+interval '10 minutes', paid_at timestamptz);
GRANT SELECT ON public.payment_orders TO authenticated; GRANT ALL ON public.payment_orders TO service_role;
ALTER TABLE public.payment_orders ENABLE ROW LEVEL SECURITY;
CREATE INDEX orders_owner ON public.payment_orders(user_id,created_at DESC);
CREATE POLICY orders_read ON public.payment_orders FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) OR (SELECT public.has_role((SELECT auth.uid()),'admin')));
CREATE FUNCTION public.confirm_order(p_id uuid,p_transaction text,p_slug text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.payment_orders; BEGIN SELECT * INTO o FROM public.payment_orders WHERE id=p_id FOR UPDATE; IF o.id IS NULL THEN RETURN false; END IF; IF o.status='paid' THEN RETURN true; END IF; UPDATE public.payment_orders SET status='paid',paid_at=now(),transaction_nsu=p_transaction,slug=p_slug WHERE id=p_id; UPDATE public.saas_accounts SET credits=credits+o.credits,plan=o.plan WHERE user_id=o.user_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.confirm_order(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_order(uuid,text,text) TO service_role;